// four legs: 2-cell-wide walls, 3 courses tall
const legCells=[1,2,8,9];
let grayLeft=7;
for(const x of legCells){
  let r=anchor('3622',71,x,0,90); grayLeft--;
  for(let c=0;c<2;c++){
    let col = grayLeft>0?71:4;
    const n=on('3622',col,r,0,0,90);
    if(n>=0){ r=n; if(col==71) grayLeft--; }
    else log('leg reject x='+x+' c='+c);
  }
}
